1	//! Layered configuration for defaults: built-in < XDG config file <
2	//! project-local file < CLI flags.
3	//!
4	//! - **XDG file** — `$XDG_CONFIG_HOME/iiac-perf/config.toml`, or
5	//!   `$HOME/.config/iiac-perf/config.toml` when `XDG_CONFIG_HOME`
6	//!   is unset. The per-user home for defaults and pin profiles.
7	//! - **Project-local file** — [`LOCAL_FILE`] in the current
8	//!   directory (no upward walk). Overrides the XDG file
9	//!   field-by-field; profiles merge by key.
10	//! - **CLI** — always wins, resolved in `main` after [`load`].
11	//!
12	//! A malformed or unreadable-but-present file is a hard error, so a
13	//! typo surfaces rather than silently reverting to built-ins.
14	
15	use std::collections::BTreeMap;
16	use std::path::PathBuf;
17	
18	use serde::Deserialize;
19	
20	use crate::bands::BandLabels;
21	
22	/// Project-local override filename, looked up in the current
23	/// directory only.
24	const LOCAL_FILE: &str = "iiac-perf.toml";
25	
26	/// Inclusive upper bound on `decimals`, mirroring the
27	/// `--decimals` CLI `value_parser` range.
28	const DECIMALS_MAX: u8 = 3;
29	
30	/// The on-disk TOML shape, before validation. Scalars are
31	/// `Option` so an absent key stays absent (letting a lower layer
32	/// or built-in default show through); unknown keys are rejected
33	/// to catch typos.
34	#[derive(Debug, Default, Deserialize)]
35	#[serde(deny_unknown_fields)]
36	struct RawConfig {
37	    /// Default `--duration` seconds.
38	    duration: Option<f64>,
39	    /// Default `--band-labels` style, as its lowercase name.
40	    band_labels: Option<String>,
41	    /// Default `--decimals` count.
42	    decimals: Option<u8>,
43	    /// Default `--settle-time` seconds.
44	    settle_time: Option<f64>,
45	    /// Default `--warm-cap` seconds.
46	    warm_cap: Option<f64>,
47	    /// Named pin profiles: name -> `--pin` core spec.
48	    #[serde(default)]
49	    profiles: BTreeMap<String, String>,
50	}
51	
52	/// The merged, validated configuration handed to `main`.
53	///
54	/// Each scalar is `Option`: `None` means "no config opinion, use
55	/// the built-in default". Profiles are a flat name->spec map.
56	#[derive(Debug, Default, PartialEq)]
57	pub struct Config {
58	    /// Default `--duration` seconds, if configured.
59	    pub duration: Option<f64>,
60	    /// Default `--band-labels` style, if configured.
61	    pub band_labels: Option<BandLabels>,
62	    /// Default `--decimals` count, if configured.
63	    pub decimals: Option<u8>,
64	    /// Default `--settle-time` seconds, if configured.
65	    pub settle_time: Option<f64>,
66	    /// Default `--warm-cap` seconds, if configured.
67	    pub warm_cap: Option<f64>,
68	    /// Named pin profiles: name -> `--pin` core spec.
69	    pub profiles: BTreeMap<String, String>,
70	}
71	
72	impl Config {
73	    /// Resolve a `--pin` spec against the configured profiles: a
74	    /// spec that names a profile expands to that profile's core
75	    /// spec; anything else is returned unchanged for
76	    /// [`crate::pin::parse_cores`] to parse as a raw core list.
77	    pub fn resolve_pin<'a>(&'a self, spec: &'a str) -> &'a str {
78	        self.profiles.get(spec).map(String::as_str).unwrap_or(spec)
79	    }
80	}
81	
82	/// The XDG config-file path: `$XDG_CONFIG_HOME/iiac-perf/config.toml`,
83	/// falling back to `$HOME/.config/...`. `None` if neither env var is
84	/// set (e.g. a stripped-down service environment).
85	fn xdg_path() -> Option<PathBuf> {
86	    let base = match std::env::var_os("XDG_CONFIG_HOME") {
87	        Some(x) if !x.is_empty() => PathBuf::from(x),
88	        _ => PathBuf::from(std::env::var_os("HOME")?).join(".config"),
89	    };
90	    Some(base.join("iiac-perf").join("config.toml"))
91	}
92	
93	/// Load and merge the XDG and project-local config files. Returns
94	/// the merged [`Config`] plus the paths of the files that actually
95	/// existed (for the startup banner). Built-in-default `Config` when
96	/// no file exists; errors on a present-but-unreadable or malformed
97	/// file.
98	///
99	/// Layering: start from the XDG file, then overlay the local file
100	/// (scalars replace, profiles merge by key), so the nearer file
101	/// wins per field.
102	pub fn load() -> Result<(Config, Vec<PathBuf>), String> {
103	    let mut raw = RawConfig::default();
104	    let mut loaded = Vec::new();
105	    if let Some(path) = xdg_path()
106	        && overlay(&mut raw, &path)?
107	    {
108	        loaded.push(path);
109	    }
110	    let local = PathBuf::from(LOCAL_FILE);
111	    if overlay(&mut raw, &local)? {
112	        loaded.push(local);
113	    }
114	    Ok((validate(raw)?, loaded))
115	}
116	
117	/// Read one config file and overlay it onto `base`: each present
118	/// scalar replaces `base`'s, and profiles are merged by key (the
119	/// file's entries win). Returns whether the file existed; a missing
120	/// file is a no-op returning `false`.
121	fn overlay(base: &mut RawConfig, path: &PathBuf) -> Result<bool, String> {
122	    let text = match std::fs::read_to_string(path) {
123	        Ok(t) => t,
124	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(false),
125	        Err(e) => return Err(format!("reading {}: {e}", path.display())),
126	    };
127	    let over: RawConfig =
128	        toml::from_str(&text).map_err(|e| format!("parsing {}: {e}", path.display()))?;
129	    if over.duration.is_some() {
130	        base.duration = over.duration;
131	    }
132	    if over.band_labels.is_some() {
133	        base.band_labels = over.band_labels;
134	    }
135	    if over.decimals.is_some() {
136	        base.decimals = over.decimals;
137	    }
138	    if over.settle_time.is_some() {
139	        base.settle_time = over.settle_time;
140	    }
141	    if over.warm_cap.is_some() {
142	        base.warm_cap = over.warm_cap;
143	    }
144	    base.profiles.extend(over.profiles);
145	    Ok(true)
146	}
147	
148	/// Validate a merged [`RawConfig`] into a [`Config`]: map the
149	/// `band_labels` name to the enum, range-check `decimals`, and
150	/// reject a negative `settle_time`.
151	fn validate(raw: RawConfig) -> Result<Config, String> {
152	    let band_labels = match raw.band_labels {
153	        None => None,
154	        Some(s) => Some(match s.as_str() {
155	            "zpn" => BandLabels::Zpn,
156	            "frac" => BandLabels::Frac,
157	            "both" => BandLabels::Both,
158	            other => {
159	                return Err(format!(
160	                    "band_labels: {other:?} is not one of zpn, frac, both"
161	                ));
162	            }
163	        }),
164	    };
165	    if let Some(d) = raw.decimals
166	        && d > DECIMALS_MAX
167	    {
168	        return Err(format!(
169	            "decimals: {d} exceeds the maximum of {DECIMALS_MAX}"
170	        ));
171	    }
172	    if let Some(t) = raw.settle_time
173	        && t < 0.0
174	    {
175	        return Err(format!("settle_time: {t} is negative"));
176	    }
177	    if let Some(t) = raw.warm_cap
178	        && t < 0.0
179	    {
180	        return Err(format!("warm_cap: {t} is negative"));
181	    }
182	    Ok(Config {
183	        duration: raw.duration,
184	        band_labels,
185	        decimals: raw.decimals,
186	        settle_time: raw.settle_time,
187	        warm_cap: raw.warm_cap,
188	        profiles: raw.profiles,
189	    })
190	}
191	
192	#[cfg(test)]
193	mod tests {
194	    use super::*;
195	
196	    fn parse(text: &str) -> Result<Config, String> {
197	        validate(toml::from_str(text).map_err(|e| e.to_string())?)
198	    }
199	
200	    #[test]
201	    fn empty_is_all_none() {
202	        assert_eq!(parse("").unwrap(), Config::default());
203	    }
204	
205	    #[test]
206	    fn scalars_parse() {
207	        let c = parse("duration = 2.5\nband_labels = \"zpn\"\ndecimals = 0\nsettle_time = 3.0\n")
208	            .unwrap();
209	        assert_eq!(c.duration, Some(2.5));
210	        assert_eq!(c.band_labels, Some(BandLabels::Zpn));
211	        assert_eq!(c.decimals, Some(0));
212	        assert_eq!(c.settle_time, Some(3.0));
213	    }
214	
215	    #[test]
216	    fn negative_settle_time_errs() {
217	        assert!(parse("settle_time = -1.0\n").is_err());
218	        // Zero is legal: it means "skip the warm".
219	        assert_eq!(parse("settle_time = 0.0\n").unwrap().settle_time, Some(0.0));
220	    }
221	
222	    #[test]
223	    fn negative_warm_cap_errs() {
224	        assert!(parse("warm_cap = -1.0\n").is_err());
225	        // Zero is legal: cap immediately, run uncertified.
226	        assert_eq!(parse("warm_cap = 0.0\n").unwrap().warm_cap, Some(0.0));
227	    }
228	
229	    #[test]
230	    fn profiles_parse_and_resolve() {
231	        let c = parse("[profiles]\nsmt = \"0,12\"\nccx = \"0,1\"\n").unwrap();
232	        assert_eq!(c.resolve_pin("smt"), "0,12");
233	        assert_eq!(c.resolve_pin("ccx"), "0,1");
234	        // A non-profile spec passes through untouched.
235	        assert_eq!(c.resolve_pin("0,3-5"), "0,3-5");
236	    }
237	
238	    #[test]
239	    fn bad_band_labels_errs() {
240	        assert!(parse("band_labels = \"nope\"\n").is_err());
241	    }
242	
243	    #[test]
244	    fn out_of_range_decimals_errs() {
245	        assert!(parse("decimals = 5\n").is_err());
246	    }
