1	//! The md -> toml filter, on its own so build.rs can share it.
2	//!
3	//! A config markdown document's `toml` fences, concatenated in
4	//! document order, form the TOML a reader parses. That rule holds
5	//! for both markdown carriers: the instance config
6	//! (`.vc-config.md`, loaded by `crate::config_md`) and the schema
7	//! prototype (`vc-config.md`, parsed by build.rs), so the filter
8	//! is a file both can pull in.
9	//!
10	//! A build script is its own crate, so build.rs declares this file
11	//! with `#[path]` rather than a crate-relative module path. Nothing
12	//! here may name a crate item or a dependency: std only, and no
13	//! intra-doc links, which would not resolve on the build-script
14	//! side.
15	
16	/// What the filter is inside of, line by line.
17	enum Fence {
18	    /// Outside any fence: prose, blanked.
19	    None,
20	    /// Inside a ```toml fence: lines pass through.
21	    Toml,
22	    /// Inside any other fence (illustration idiom): blanked.
23	    Other,
24	}
25	
26	/// Extract the TOML a config markdown document carries.
27	///
28	/// - `toml`-tagged fence interiors pass through verbatim.
29	/// - Every other line (prose, fence markers, other fences'
30	///   interiors) is blanked rather than removed, so the result has
31	///   the source's line count and any parse diagnostic points at
32	///   the real line.
33	/// - The tag must be exactly `toml` (` ```toml `); a fence tagged
34	///   otherwise or untagged is illustration and is ignored.
35	/// - An unclosed fence is an error naming its opening line.
36	pub fn md_to_toml(content: &str) -> Result<String, String> {
37	    let mut state = Fence::None;
38	    let mut opened_at = 0usize;
39	    let mut out = String::with_capacity(content.len());
40	    for (idx, line) in content.lines().enumerate() {
41	        let trimmed = line.trim_start();
42	        match state {
43	            Fence::None => {
44	                if let Some(info) = trimmed.strip_prefix("```") {
45	                    state = if info.trim() == "toml" {
46	                        Fence::Toml
47	                    } else {
48	                        Fence::Other
49	                    };
50	                    opened_at = idx + 1;
51	                }
52	            }
53	            Fence::Toml => {
54	                if is_fence_close(trimmed) {
55	                    state = Fence::None;
56	                } else {
57	                    out.push_str(line);
58	                }
59	            }
60	            Fence::Other => {
61	                if is_fence_close(trimmed) {
62	                    state = Fence::None;
63	                }
64	            }
65	        }
66	        out.push('\n');
67	    }
68	    if matches!(state, Fence::None) {
69	        Ok(out)
70	    } else {
71	        Err(format!("unclosed fence opened at line {opened_at}"))
72	    }
73	}
74	
75	/// True when a (trim_start'ed) line closes a fence: backticks with
76	/// nothing but whitespace after them.
77	fn is_fence_close(trimmed: &str) -> bool {
78	    trimmed
79	        .strip_prefix("```")
80	        .is_some_and(|rest| rest.trim().is_empty())
81	}
82

